old:
.barcode-print-wrap .barcode-stripes {
    display: block;
    box-sizing: border-box;
    width: 100%;
    height: 100%;
    overflow: hidden;
}

new:
.barcode-print-wrap .barcode-stripes {
    display: block;
    box-sizing: border-box;
    width: auto;
    max-width: 100%;
    height: auto;
    overflow: hidden;
}
.barcode-print-wrap.barcode-selected {
    outline: 2px solid #5a3b8c;
    outline-offset: 1px;
}
.barcode-resize-handle {
    position: absolute;
    right: -3px;
    bottom: -3px;
    width: 12px;
    height: 12px;
    cursor: ew-resize;
    background: #5a3b8c;
    border: 1px solid #fff;
    border-radius: 2px;
    z-index: 6;
    box-sizing: border-box;
}
.barcode-resize-handle:hover {
    background: #7c3aed;
}
